<script lang="ts">
  import { onMount } from 'svelte'; import { goto } from '$app/navigation';
  import { TeacherApi, readableError, type ClassMaterial, type ClassRoom } from '$lib/teacher-api'; import TeacherNav from '$lib/teacher/TeacherNav.svelte'; import '$lib/teacher/teacher.css';
  const api = new TeacherApi(); let ready = false; let busy = false; let error = ''; let notice = ''; let classes: readonly ClassRoom[] = []; let selectedClassId = ''; let materials: readonly ClassMaterial[] = []; let selectedFile: File | undefined;
  onMount(() => { void initialise(); });
  async function initialise(): Promise<void> { if (!await api.restoreTeacher()) { await goto('/teacher'); return; } ready = true; await refresh(); }
  async function refresh(): Promise<void> { const page = await api.classes(); classes = page.items; if (!classes.some((item) => item.id === selectedClassId)) selectedClassId = classes[0]?.id ?? ''; materials = selectedClassId ? await api.materials(selectedClassId) : []; }
  async function work(action: () => Promise<void>): Promise<void> { busy = true; error = ''; notice = ''; try { await action(); } catch (cause) { error = readableError(cause); } finally { busy = false; } }
  async function upload(): Promise<void> { if (!selectedFile || !selectedClassId) { error = '請選擇班級與教材檔案。'; return; } await work(async () => { await api.uploadMaterial(selectedClassId, selectedFile!); selectedFile = undefined; await refresh(); notice = '教材已上傳，已加入此班的學生可立即下載。'; }); }
  async function remove(id: string): Promise<void> { await work(async () => { await api.deleteMaterial(selectedClassId, id); await refresh(); notice = '教材已撤回。'; }); }
  async function logout(): Promise<void> { await api.logout(); await goto('/teacher'); }
</script>
<main aria-busy={!ready}><TeacherNav current="materials" onLogout={logout}/>{#if !ready}<p>正在確認教師登入狀態…</p>{:else}<h2>班級教材</h2><p class="muted">已加入指定班級的學生才能看見及下載教材。上限 25 MB；支援 PDF、圖片、純文字、Office Open XML 與 ZIP。</p><div aria-live="polite">{#if notice}<p class="notice">{notice}</p>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}</div><section class="panel"><label for="material-class">班級</label><select id="material-class" bind:value={selectedClassId} on:change={() => void work(refresh)}>{#each classes as room}<option value={room.id}>{room.name}</option>{/each}</select><label for="material-file">教材檔案</label><input id="material-file" type="file" accept=".pdf,.txt,.png,.jpg,.jpeg,.zip,.docx,.pptx,.xlsx" on:change={(event) => selectedFile = (event.currentTarget.files ?? [])[0]}/><div class="actions"><button class="primary" on:click={() => void upload()} disabled={busy || !selectedClassId}>上傳教材</button><button on:click={() => void work(refresh)} disabled={busy}>重新整理</button></div></section><section class="panel"><h3>已發佈教材（{materials.length}）</h3>{#if materials.length === 0}<p class="muted">尚未上傳教材。</p>{:else}<div class="table-wrap"><table><thead><tr><th>檔案</th><th>大小</th><th>上傳時間</th><th>操作</th></tr></thead><tbody>{#each materials as material}<tr><td>{material.displayFilename}</td><td>{material.byteLength.toLocaleString()} bytes</td><td>{new Date(material.createdAtUtc).toLocaleString()}</td><td><button class="danger small" on:click={() => void remove(material.id)} disabled={busy}>撤回</button></td></tr>{/each}</tbody></table></div>{/if}</section>{/if}</main>
